def count_matching_pairs(a, b, target):
    i, j = 0, len(b) - 1
    count = 0
    while i < len(a) and j >= 0:
        s = a[i] + b[j]
        if s < target:
            i += 1
        elif s > target:
            j -= 1
        else:
            x, y = a[i], b[j]
            run_a = run_b = 0
            while i < len(a) and a[i] == x:
                i += 1
                run_a += 1
            while j >= 0 and b[j] == y:
                j -= 1
                run_b += 1
            count += run_a * run_b
    return count

